import 'package:flutter_riverpod/flutter_riverpod.dart';

final counterProvider = StateProvider<int>((ref) => 0);

void main() {
  runApp(const ProviderScope(child: MyApp()));
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(home: CounterPage());
  }
}

class CounterPage extends ConsumerWidget {
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final count = ref.watch(counterProvider);

    return Scaffold(
      body: Center(child: Text('$count')),
      floatingActionButton: FloatingActionButton(
        onPressed: () => ref.read(counterProvider.notifier).state++,
        child: Icon(Icons.add),
      ),
    );
  }
}

import 'package:flutter_riverpod/flutter_riverpod.dart';

class CounterState {
  final int value;
  final bool isLoading;

  CounterState({this.value = 0, this.isLoading = false});

  CounterState copyWith({int? value, bool? isLoading}) => CounterState(
    value: value ?? this.value,
    isLoading: isLoading ?? this.isLoading,
  );
}

class CounterNotifier extends StateNotifier<CounterState> {
  CounterNotifier() : super(CounterState());

  void increment() => state = state.copyWith(value: state.value + 1);
  void decrement() => state = state.copyWith(value: state.value - 1);

  Future<void> incrementAsync() async {
    state = state.copyWith(isLoading: true);
    await Future.delayed(Duration(seconds: 1));
    state = state.copyWith(value: state.value + 1, isLoading: false);
  }
}

final counterNotifierProvider = StateNotifierProvider<CounterNotifier, CounterState>(
  (ref) => CounterNotifier(),
);

import 'package:equatable/equatable.dart';

abstract class CounterEvent extends Equatable {
  const CounterEvent();
  @override
  List<Object?> get props => [];
}

class CounterIncrement extends CounterEvent {}
class CounterDecrement extends CounterEvent {}
class CounterReset extends CounterEvent {}

class CounterState extends Equatable {
  final int value;

  const CounterState({this.value = 0});

  CounterState copyWith({int? value}) => CounterState(value: value ?? this.value);

  @override
  List<Object?> get props => [value];
}

import 'package:flutter_bloc/flutter_bloc.dart';

class CounterBloc extends Bloc<CounterEvent, CounterState> {
  CounterBloc() : super(const CounterState()) {
    on<CounterIncrement>((event, emit) {
      emit(state.copyWith(value: state.value + 1));
    });

    on<CounterDecrement>((event, emit) {
      emit(state.copyWith(value: state.value - 1));
    });

    on<CounterReset>((event, emit) {
      emit(const CounterState());
    });
  }
}

